export default [{"id":"P1-X1","moduleId":"P1","title":"Badge d’énergie","level":1,"kind":"compléter","prompt":"Complète <code>energie_restante(depart, cout)</code> pour renvoyer l’énergie restante après une action.","starter":"def energie_restante(depart, cout):\n    return ____________","tests":[{"label":"cas simple","expr":"energie_restante(10, 3) == 7"},{"label":"tout dépensé","expr":"energie_restante(5, 5) == 0"}],"hints":["Il faut soustraire le coût à l’énergie de départ.","L’expression est depart - cout."],"solution":"def energie_restante(depart, cout):\n    return depart - cout","tags":["affectation","expression","jeu"]},{"id":"P1-X2","moduleId":"P1","title":"Pseudo complet","level":1,"kind":"écrire","prompt":"Écris <code>pseudo(prenom, numero)</code> qui renvoie une chaîne formée du prénom suivi du numéro, par exemple <code>pseudo('Ada', 7)</code> renvoie <code>'Ada7'</code>.","starter":"def pseudo(prenom, numero):\n    pass","tests":[{"label":"Ada7","expr":"pseudo('Ada', 7) == 'Ada7'"},{"label":"nsi42","expr":"pseudo('nsi', 42) == 'nsi42'"}],"hints":["Le numéro doit devenir une chaîne avec str.","Concatène deux chaînes avec +."],"solution":"def pseudo(prenom, numero):\n    return prenom + str(numero)","tags":["str","conversion","concaténation"]},{"id":"P1-X3","moduleId":"P1","title":"Déboguer le score","level":1,"kind":"déboguer","prompt":"La fonction doit renvoyer le score après ajout d’un bonus. Corrige l’erreur.","starter":"def nouveau_score(score, bonus):\n    score == score + bonus\n    return score","tests":[{"label":"bonus","expr":"nouveau_score(10, 4) == 14"},{"label":"bonus nul","expr":"nouveau_score(3, 0) == 3"}],"hints":["== compare ; = affecte.","La deuxième ligne doit modifier score."],"solution":"def nouveau_score(score, bonus):\n    score = score + bonus\n    return score","tags":["affectation","débogage"]},{"id":"P1-X4","moduleId":"P1","title":"Temps de vidéo","level":2,"kind":"transfert","prompt":"Une vidéo dure un nombre entier de secondes. Écris <code>minutes_secondes(duree)</code> qui renvoie un tuple <code>(minutes, secondes)</code>.","starter":"def minutes_secondes(duree):\n    pass","tests":[{"label":"125 s","expr":"minutes_secondes(125) == (2, 5)"},{"label":"60 s","expr":"minutes_secondes(60) == (1, 0)"},{"label":"0 s","expr":"minutes_secondes(0) == (0, 0)"}],"hints":["// donne le quotient entier.","% donne le reste."],"solution":"def minutes_secondes(duree):\n    return duree // 60, duree % 60","tags":["division entière","modulo","tuple"]},{"id":"P1-X5","moduleId":"P1","title":"Pixels d’une bannière","level":2,"kind":"écrire","prompt":"Écris <code>nb_pixels(largeur, hauteur)</code> qui renvoie le nombre de pixels d’une image rectangulaire. Aucune connaissance géométrique n’est nécessaire : la formule est <code>largeur × hauteur</code>.","starter":"def nb_pixels(largeur, hauteur):\n    pass","tests":[{"label":"HD miniature","expr":"nb_pixels(320, 180) == 57600"},{"label":"une ligne","expr":"nb_pixels(8, 1) == 8"}],"hints":["Utilise l’opérateur *.","La formule est donnée dans l’énoncé."],"solution":"def nb_pixels(largeur, hauteur):\n    return largeur * hauteur","tags":["expression","numérique","image"]},{"id":"P2-X1","moduleId":"P2","title":"Mode silencieux","level":1,"kind":"compléter","prompt":"Complète <code>notifier(urgent, silencieux)</code> : la notification doit être envoyée si elle est urgente OU si le mode silencieux est désactivé.","starter":"def notifier(urgent, silencieux):\n    return urgent ____ (not silencieux)","tests":[{"label":"urgent","expr":"notifier(True, True) is True"},{"label":"normal actif","expr":"notifier(False, False) is True"},{"label":"normal silencieux","expr":"notifier(False, True) is False"}],"hints":["Le mot logique pour OU est or."],"solution":"def notifier(urgent, silencieux):\n    return urgent or (not silencieux)","tags":["booléens","or","not"]},{"id":"P2-X2","moduleId":"P2","title":"Accès au tournoi","level":1,"kind":"écrire","prompt":"Écris <code>admis_tournoi(age, autorisation)</code>. Un joueur est admis s’il a au moins 16 ans, ou s’il possède une autorisation.","starter":"def admis_tournoi(age, autorisation):\n    pass","tests":[{"label":"16 ans","expr":"admis_tournoi(16, False) is True"},{"label":"autorisation","expr":"admis_tournoi(14, True) is True"},{"label":"refus","expr":"admis_tournoi(14, False) is False"}],"hints":["Traduis littéralement la règle avec >= et or."],"solution":"def admis_tournoi(age, autorisation):\n    return age >= 16 or autorisation","tags":["condition","booléens","contexte"]},{"id":"P2-X3","moduleId":"P2","title":"Déboguer la batterie","level":2,"kind":"déboguer","prompt":"Le téléphone affiche <code>'faible'</code> si la batterie est inférieure ou égale à 20 %, sinon <code>'ok'</code>. Corrige la fonction.","starter":"def batterie(niveau):\n    if niveau < 20:\n        return 'faible'\n    else:\n        return 'ok'","tests":[{"label":"20 est faible","expr":"batterie(20) == 'faible'"},{"label":"19 est faible","expr":"batterie(19) == 'faible'"},{"label":"21 est ok","expr":"batterie(21) == 'ok'"}],"hints":["Le seuil 20 est inclus.","Utilise <=."],"solution":"def batterie(niveau):\n    if niveau <= 20:\n        return 'faible'\n    return 'ok'","tags":["frontière","débogage","if"]},{"id":"P2-X4","moduleId":"P2","title":"Feu tricolore","level":2,"kind":"écrire","prompt":"Écris <code>action_feu(couleur)</code> : <code>'rouge'</code> → <code>'stop'</code>, <code>'orange'</code> → <code>'ralentir'</code>, <code>'vert'</code> → <code>'passer'</code>, toute autre valeur → <code>'inconnu'</code>.","starter":"def action_feu(couleur):\n    pass","tests":[{"label":"rouge","expr":"action_feu('rouge') == 'stop'"},{"label":"orange","expr":"action_feu('orange') == 'ralentir'"},{"label":"vert","expr":"action_feu('vert') == 'passer'"},{"label":"autre","expr":"action_feu('bleu') == 'inconnu'"}],"hints":["Une chaîne if / elif / elif / else convient."],"solution":"def action_feu(couleur):\n    if couleur == 'rouge':\n        return 'stop'\n    elif couleur == 'orange':\n        return 'ralentir'\n    elif couleur == 'vert':\n        return 'passer'\n    return 'inconnu'","tags":["if","elif","chaînes"]},{"id":"P2-X5","moduleId":"P2","title":"Mot de passe acceptable","level":3,"kind":"transfert","prompt":"Écris <code>acceptable(longueur, chiffre, interdit)</code>. Un mot de passe est accepté s’il contient au moins 8 caractères, contient un chiffre et n’est pas marqué interdit.","starter":"def acceptable(longueur, chiffre, interdit):\n    pass","tests":[{"label":"accepté","expr":"acceptable(10, True, False) is True"},{"label":"trop court","expr":"acceptable(7, True, False) is False"},{"label":"sans chiffre","expr":"acceptable(10, False, False) is False"},{"label":"interdit","expr":"acceptable(12, True, True) is False"}],"hints":["Les trois exigences doivent être vraies ensemble.","La dernière se formule not interdit."],"solution":"def acceptable(longueur, chiffre, interdit):\n    return longueur >= 8 and chiffre and not interdit","tags":["and","not","sécurité"]},{"id":"P3-X1","moduleId":"P3","title":"Points d’une quête","level":1,"kind":"compléter","prompt":"Complète la boucle pour additionner les points sans utiliser <code>sum</code>.","starter":"def points_total(points):\n    total = 0\n    for p in points:\n        ____________\n    return total","tests":[{"label":"quête","expr":"points_total([5,10,3]) == 18"},{"label":"vide","expr":"points_total([]) == 0"}],"hints":["À chaque tour, ajoute p à total."],"solution":"def points_total(points):\n    total = 0\n    for p in points:\n        total += p\n    return total","tags":["for","accumulateur","jeu"]},{"id":"P3-X2","moduleId":"P3","title":"Messages non lus","level":1,"kind":"écrire","prompt":"Écris <code>compte_non_lus(etats)</code> qui compte combien de chaînes valent <code>'non lu'</code>.","starter":"def compte_non_lus(etats):\n    pass","tests":[{"label":"trois messages","expr":"compte_non_lus(['lu','non lu','non lu','lu','non lu']) == 3"},{"label":"aucun","expr":"compte_non_lus([]) == 0"}],"hints":["Initialise un compteur à 0.","Incrémente seulement si l’état correspond."],"solution":"def compte_non_lus(etats):\n    n = 0\n    for etat in etats:\n        if etat == 'non lu':\n            n += 1\n    return n","tags":["for","compteur","messages"]},{"id":"P3-X3","moduleId":"P3","title":"Déboguer le compte à rebours","level":2,"kind":"déboguer","prompt":"La fonction doit renvoyer la liste <code>[n, n-1, ..., 0]</code>. Corrige la boucle infinie.","starter":"def compte_a_rebours(n):\n    resultat = []\n    while n >= 0:\n        resultat.append(n)\n        n += 1\n    return resultat","tests":[{"label":"3","expr":"compte_a_rebours(3) == [3,2,1,0]"},{"label":"0","expr":"compte_a_rebours(0) == [0]"}],"hints":["Le variant doit se rapprocher de la condition d’arrêt.","n doit diminuer."],"solution":"def compte_a_rebours(n):\n    resultat = []\n    while n >= 0:\n        resultat.append(n)\n        n -= 1\n    return resultat","tags":["while","variant","débogage"]},{"id":"P3-X4","moduleId":"P3","title":"Première alerte","level":2,"kind":"écrire","prompt":"Écris <code>premiere_alerte(valeurs, seuil)</code> qui renvoie l’indice de la première valeur strictement supérieure au seuil, ou -1 si aucune.","starter":"def premiere_alerte(valeurs, seuil):\n    pass","tests":[{"label":"alerte","expr":"premiere_alerte([3,5,12,9], 10) == 2"},{"label":"aucune","expr":"premiere_alerte([1,2,3], 10) == -1"},{"label":"égalité non alerte","expr":"premiere_alerte([10,11], 10) == 1"}],"hints":["Parcours les indices avec range(len(valeurs)).","Retourne dès le premier dépassement."],"solution":"def premiere_alerte(valeurs, seuil):\n    for i in range(len(valeurs)):\n        if valeurs[i] > seuil:\n            return i\n    return -1","tags":["for","indice","capteur"]},{"id":"P3-X5","moduleId":"P3","title":"Nombre de tentatives","level":3,"kind":"transfert","prompt":"On divise une zone de recherche entière par 2 jusqu’à obtenir une taille 1. Écris <code>reductions(taille)</code> qui compte le nombre de divisions entières par 2 nécessaires tant que taille > 1.","starter":"def reductions(taille):\n    pass","tests":[{"label":"taille 1","expr":"reductions(1) == 0"},{"label":"taille 8","expr":"reductions(8) == 3"},{"label":"taille 9","expr":"reductions(9) == 3"}],"hints":["Utilise while taille > 1.","À chaque tour : taille //= 2 et incrémente le compteur."],"solution":"def reductions(taille):\n    n = 0\n    while taille > 1:\n        taille //= 2\n        n += 1\n    return n","tags":["while","logarithmique","dichotomie"]},{"id":"P4-X1","moduleId":"P4","title":"Validation d’un pseudo","level":1,"kind":"compléter","prompt":"Complète <code>longueur_valide(pseudo)</code> : un pseudo doit contenir entre 3 et 12 caractères inclus.","starter":"def longueur_valide(pseudo):\n    return ____ <= len(pseudo) <= ____","tests":[{"label":"3 caractères","expr":"longueur_valide('Ada') is True"},{"label":"12 caractères","expr":"longueur_valide('abcdefghijkl') is True"},{"label":"trop court","expr":"longueur_valide('ab') is False"}],"hints":["Les deux bornes sont 3 et 12."],"solution":"def longueur_valide(pseudo):\n    return 3 <= len(pseudo) <= 12","tags":["contrat","frontière","str"]},{"id":"P4-X2","moduleId":"P4","title":"Test manquant","level":2,"kind":"déboguer","prompt":"Cette fonction doit renvoyer le premier élément d’une liste non vide. Ajoute une précondition explicite avec <code>assert</code>.","starter":"def premier(tab):\n    return tab[0]","tests":[{"label":"valeur","expr":"premier([8,4]) == 8"},{"label":"liste vide refusée","expr":"premier([])","raises":"AssertionError"}],"hints":["La précondition concerne len(tab).","Écris assert len(tab) > 0 avant le return."],"solution":"def premier(tab):\n    assert len(tab) > 0\n    return tab[0]","tags":["assert","précondition","tests"]},{"id":"P4-X3","moduleId":"P4","title":"Meilleur des trois","level":2,"kind":"écrire","prompt":"Écris <code>maximum3(a, b, c)</code> sans utiliser <code>max</code>. Les valeurs peuvent être égales.","starter":"def maximum3(a, b, c):\n    pass","tests":[{"label":"a","expr":"maximum3(9,2,4) == 9"},{"label":"b","expr":"maximum3(2,9,4) == 9"},{"label":"c","expr":"maximum3(2,4,9) == 9"},{"label":"égalité","expr":"maximum3(7,7,3) == 7"}],"hints":["Tu peux mémoriser un meilleur courant.","Compare successivement b puis c."],"solution":"def maximum3(a, b, c):\n    m = a\n    if b > m:\n        m = b\n    if c > m:\n        m = c\n    return m","tags":["fonction","tests","if"]},{"id":"P4-X4","moduleId":"P4","title":"Tester un identifiant","level":2,"kind":"transfert","prompt":"Écris <code>identifiant_valide(texte)</code> : il doit être non vide, commencer par une lettre et ne contenir ensuite que des lettres ou chiffres. Utilise les méthodes <code>isalpha()</code> et <code>isalnum()</code>.","starter":"def identifiant_valide(texte):\n    pass","tests":[{"label":"valide","expr":"identifiant_valide('nsi42') is True"},{"label":"vide","expr":"identifiant_valide('') is False"},{"label":"commence par chiffre","expr":"identifiant_valide('42nsi') is False"},{"label":"symbole","expr":"identifiant_valide('nsi-42') is False"}],"hints":["Traite d’abord le cas vide.","Le premier caractère doit satisfaire isalpha(), puis toute la chaîne peut satisfaire isalnum()."],"solution":"def identifiant_valide(texte):\n    if texte == '':\n        return False\n    return texte[0].isalpha() and texte.isalnum()","tags":["contrat","chaîne","validation"]},{"id":"P4-X5","moduleId":"P4","title":"Cas frontières d’un tarif","level":3,"kind":"écrire","prompt":"Écris <code>tarif(age)</code> : moins de 12 ans → 5, de 12 à 17 inclus → 8, à partir de 18 → 12. La fonction exige <code>age >= 0</code>.","starter":"def tarif(age):\n    pass","tests":[{"label":"précondition","expr":"tarif(-1)","raises":"AssertionError"},{"label":"11 ans","expr":"tarif(11) == 5"},{"label":"12 ans","expr":"tarif(12) == 8"},{"label":"17 ans","expr":"tarif(17) == 8"},{"label":"18 ans","expr":"tarif(18) == 12"}],"hints":["Commence par assert age >= 0.","Teste les seuils dans l’ordre croissant."],"solution":"def tarif(age):\n    assert age >= 0\n    if age < 12:\n        return 5\n    if age < 18:\n        return 8\n    return 12","tags":["frontières","assert","conditions"]},{"id":"P5-X1","moduleId":"P5","title":"Initiales","level":1,"kind":"écrire","prompt":"Écris <code>initiales(prenom, nom)</code> qui renvoie les deux premières lettres en majuscules séparées par un point, par exemple <code>'A.L'</code>. Les deux chaînes sont non vides.","starter":"def initiales(prenom, nom):\n    pass","tests":[{"label":"Ada Lovelace","expr":"initiales('Ada','Lovelace') == 'A.L'"},{"label":"grace hopper","expr":"initiales('grace','hopper') == 'G.H'"}],"hints":["Utilise l’indice 0.","upper() met une chaîne en majuscules."],"solution":"def initiales(prenom, nom):\n    return prenom[0].upper() + '.' + nom[0].upper()","tags":["chaînes","indexation","texte"]},{"id":"P5-X2","moduleId":"P5","title":"Compter les hashtags","level":1,"kind":"compléter","prompt":"Complète la fonction qui compte le caractère <code>#</code> dans un message.","starter":"def nb_hashtags(message):\n    n = 0\n    for c in message:\n        if ____________:\n            n += 1\n    return n","tests":[{"label":"deux","expr":"nb_hashtags('#nsi #python') == 2"},{"label":"aucun","expr":"nb_hashtags('bonjour') == 0"}],"hints":["Compare c à '#'."],"solution":"def nb_hashtags(message):\n    n = 0\n    for c in message:\n        if c == '#':\n            n += 1\n    return n","tags":["chaînes","boucle","réseaux sociaux"]},{"id":"P5-X3","moduleId":"P5","title":"Déboguer le miroir","level":2,"kind":"déboguer","prompt":"La fonction doit renvoyer le texte renversé sans slice. Corrige-la.","starter":"def miroir(texte):\n    resultat = ''\n    for i in range(len(texte)):\n        resultat += texte[i]\n    return resultat","tests":[{"label":"abc","expr":"miroir('abc') == 'cba'"},{"label":"vide","expr":"miroir('') == ''"}],"hints":["L’indice lu doit partir de la fin.","Le caractère symétrique est texte[len(texte)-1-i]."],"solution":"def miroir(texte):\n    resultat = ''\n    for i in range(len(texte)):\n        resultat += texte[len(texte)-1-i]\n    return resultat","tags":["indexation","débogage","sans slice"]},{"id":"P5-X4","moduleId":"P5","title":"Masquer un secret","level":2,"kind":"écrire","prompt":"Écris <code>masque(texte, caractere='*')</code> qui renvoie une chaîne de même longueur composée uniquement du caractère donné.","starter":"def masque(texte, caractere='*'):\n    pass","tests":[{"label":"secret","expr":"masque('secret') == '******'"},{"label":"autre caractère","expr":"masque('abc','#') == '###'"},{"label":"vide","expr":"masque('') == ''"}],"hints":["Construis progressivement resultat dans une boucle.","Le contenu du texte n’est pas utile, seulement son nombre de caractères."],"solution":"def masque(texte, caractere='*'):\n    resultat = ''\n    for _ in texte:\n        resultat += caractere\n    return resultat","tags":["chaînes","construction","sécurité"]},{"id":"P5-X5","moduleId":"P5","title":"Détecter un doublon voisin","level":3,"kind":"transfert","prompt":"Écris <code>doublon_voisin(texte)</code> qui renvoie vrai si deux caractères consécutifs sont identiques.","starter":"def doublon_voisin(texte):\n    pass","tests":[{"label":"lettres doubles","expr":"doublon_voisin('ballon') is True"},{"label":"aucun","expr":"doublon_voisin('python') is False"},{"label":"court","expr":"doublon_voisin('') is False"}],"hints":["Compare texte[i] et texte[i-1] à partir de l’indice 1.","Retourne True dès la première égalité."],"solution":"def doublon_voisin(texte):\n    for i in range(1, len(texte)):\n        if texte[i] == texte[i-1]:\n            return True\n    return False","tags":["chaînes","voisinage","transfert"]},{"id":"P6-X1","moduleId":"P6","title":"Inventaire filtré","level":1,"kind":"écrire","prompt":"Écris <code>objets_longs(objets)</code> qui renvoie les chaînes de longueur au moins 5, dans le même ordre.","starter":"def objets_longs(objets):\n    pass","tests":[{"label":"filtre","expr":"objets_longs(['clé','lampe','carte','arc']) == ['lampe','carte']"},{"label":"vide","expr":"objets_longs([]) == []"}],"hints":["Construis une nouvelle liste.","Teste len(objet) >= 5."],"solution":"def objets_longs(objets):\n    resultat = []\n    for objet in objets:\n        if len(objet) >= 5:\n            resultat.append(objet)\n    return resultat","tags":["liste","filtrage","inventaire"]},{"id":"P6-X2","moduleId":"P6","title":"Pixels positifs","level":1,"kind":"compléter","prompt":"Complète la compréhension qui remplace chaque valeur négative par 0.","starter":"def normalise_pixels(valeurs):\n    return [____________ for x in valeurs]","tests":[{"label":"normalisation","expr":"normalise_pixels([-2,5,-1,8]) == [0,5,0,8]"},{"label":"vide","expr":"normalise_pixels([]) == []"}],"hints":["Utilise une expression conditionnelle : x if x >= 0 else 0."],"solution":"def normalise_pixels(valeurs):\n    return [x if x >= 0 else 0 for x in valeurs]","tags":["compréhension","liste","image"]},{"id":"P6-X3","moduleId":"P6","title":"Déboguer la copie d’inventaire","level":2,"kind":"déboguer","prompt":"La fonction veut ajouter un objet à une copie sans modifier l’inventaire reçu. Corrige-la.","starter":"def avec_objet(inventaire, objet):\n    copie = inventaire\n    copie.append(objet)\n    return copie","tests":[{"label":"résultat","expr":"avec_objet(['clé'],'lampe') == ['clé','lampe']"},{"label":"entrée préservée","expr":"(lambda x: (avec_objet(x,'lampe'), x)[1])(['clé']) == ['clé']"}],"hints":["copie = inventaire crée un alias.","Crée une nouvelle liste avec list(inventaire)."],"solution":"def avec_objet(inventaire, objet):\n    copie = list(inventaire)\n    copie.append(objet)\n    return copie","tags":["alias","mutabilité","débogage"]},{"id":"P6-X4","moduleId":"P6","title":"Ligne la plus chargée","level":2,"kind":"écrire","prompt":"Une grille est une liste de listes d’entiers 0 ou 1. Écris <code>indice_ligne_max(grille)</code> qui renvoie l’indice de la ligne contenant le plus de 1. La grille est non vide. Sans <code>sum</code> ni <code>max</code>.","starter":"def indice_ligne_max(grille):\n    pass","tests":[{"label":"milieu","expr":"indice_ligne_max([[1,0],[1,1],[0,0]]) == 1"},{"label":"première en cas d’égalité","expr":"indice_ligne_max([[1],[1]]) == 0"}],"hints":["Crée un petit compteur pour chaque ligne.","Mémorise le meilleur indice et son score."],"solution":"def indice_ligne_max(grille):\n    meilleur_i = 0\n    meilleur_score = -1\n    for i in range(len(grille)):\n        score = 0\n        for x in grille[i]:\n            if x == 1:\n                score += 1\n        if score > meilleur_score:\n            meilleur_score = score\n            meilleur_i = i\n    return meilleur_i","tags":["tableau 2D","boucles imbriquées","grille"]},{"id":"P6-X5","moduleId":"P6","title":"Déplacement dans une carte","level":3,"kind":"transfert","prompt":"Une position est <code>[ligne, colonne]</code>. Écris <code>deplace(position, direction)</code> qui renvoie une nouvelle position après <code>'N'</code>, <code>'S'</code>, <code>'E'</code> ou <code>'O'</code>, sans modifier la liste reçue.","starter":"def deplace(position, direction):\n    pass","tests":[{"label":"nord","expr":"deplace([3,4],'N') == [2,4]"},{"label":"est","expr":"deplace([3,4],'E') == [3,5]"},{"label":"entrée intacte","expr":"(lambda p: (deplace(p,'S'),p)[1])([1,2]) == [1,2]"}],"hints":["Commence par copier la position.","N/S modifient la ligne, E/O la colonne."],"solution":"def deplace(position, direction):\n    p = list(position)\n    if direction == 'N':\n        p[0] -= 1\n    elif direction == 'S':\n        p[0] += 1\n    elif direction == 'E':\n        p[1] += 1\n    elif direction == 'O':\n        p[1] -= 1\n    return p","tags":["liste","carte","transfert"]},{"id":"P7-X1","moduleId":"P7","title":"Profil joueur","level":1,"kind":"compléter","prompt":"Complète la fonction qui crée un dictionnaire avec les clés <code>'nom'</code> et <code>'niveau'</code>.","starter":"def profil(nom, niveau):\n    return {'nom': ________, 'niveau': ________}","tests":[{"label":"profil","expr":"profil('Ada',3) == {'nom':'Ada','niveau':3}"}],"hints":["Place les paramètres nom et niveau comme valeurs."],"solution":"def profil(nom, niveau):\n    return {'nom': nom, 'niveau': niveau}","tags":["dictionnaire","construction"]},{"id":"P7-X2","moduleId":"P7","title":"Compter les extensions","level":2,"kind":"écrire","prompt":"Écris <code>extensions(fichiers)</code> qui compte les extensions déjà fournies sous forme de chaînes, par exemple <code>['py','html','py']</code> → <code>{'py':2,'html':1}</code>.","starter":"def extensions(fichiers):\n    pass","tests":[{"label":"fréquences","expr":"extensions(['py','html','py']) == {'py':2,'html':1}"},{"label":"vide","expr":"extensions([]) == {}"}],"hints":["Utilise un dictionnaire de fréquences."],"solution":"def extensions(fichiers):\n    d = {}\n    for ext in fichiers:\n        if ext not in d:\n            d[ext] = 0\n        d[ext] += 1\n    return d","tags":["dictionnaire","fréquences","fichiers"]},{"id":"P7-X3","moduleId":"P7","title":"Déboguer la mise à jour","level":2,"kind":"déboguer","prompt":"La fonction doit ajouter <code>points</code> au score du joueur. Si le joueur n’existe pas, son score initial vaut 0. Corrige-la.","starter":"def ajoute_score(scores, joueur, points):\n    scores[joueur] += points\n    return scores","tests":[{"label":"existant","expr":"ajoute_score({'Ada':10},'Ada',5) == {'Ada':15}"},{"label":"nouveau","expr":"ajoute_score({},'Linus',3) == {'Linus':3}"}],"hints":["Teste d’abord si joueur est absent du dictionnaire.","Dans ce cas, initialise scores[joueur] à 0."],"solution":"def ajoute_score(scores, joueur, points):\n    if joueur not in scores:\n        scores[joueur] = 0\n    scores[joueur] += points\n    return scores","tags":["dictionnaire","débogage","clé absente"]},{"id":"P7-X4","moduleId":"P7","title":"Inverser un annuaire","level":2,"kind":"écrire","prompt":"Un dictionnaire associe un identifiant à un pseudo, et les pseudos sont uniques. Écris <code>inverse(annuaire)</code> qui associe chaque pseudo à son identifiant.","starter":"def inverse(annuaire):\n    pass","tests":[{"label":"inverse","expr":"inverse({1:'Ada',2:'Grace'}) == {'Ada':1,'Grace':2}"},{"label":"vide","expr":"inverse({}) == {}"}],"hints":["Parcours annuaire.items().","Dans le nouveau dictionnaire, la valeur devient la clé."],"solution":"def inverse(annuaire):\n    resultat = {}\n    for identifiant, pseudo in annuaire.items():\n        resultat[pseudo] = identifiant\n    return resultat","tags":["dictionnaire","items","transformation"]},{"id":"P7-X5","moduleId":"P7","title":"Top catégorie","level":3,"kind":"transfert","prompt":"Écris <code>categorie_majoritaire(categories)</code> qui reçoit une liste de chaînes non vide et renvoie une catégorie ayant le plus grand nombre d’occurrences. En cas d’égalité, conserve celle rencontrée en premier.","starter":"def categorie_majoritaire(categories):\n    pass","tests":[{"label":"majoritaire","expr":"categorie_majoritaire(['jeu','outil','jeu','demo']) == 'jeu'"},{"label":"égalité première","expr":"categorie_majoritaire(['a','b']) == 'a'"}],"hints":["Commence par construire les fréquences.","Puis reparcours la liste d’origine pour respecter l’ordre en cas d’égalité."],"solution":"def categorie_majoritaire(categories):\n    f = {}\n    for c in categories:\n        if c not in f:\n            f[c] = 0\n        f[c] += 1\n    meilleur = categories[0]\n    for c in categories:\n        if f[c] > f[meilleur]:\n            meilleur = c\n    return meilleur","tags":["dictionnaire","fréquences","transfert"]},{"id":"P8-X1","moduleId":"P8","title":"Sélection de jeux","level":1,"kind":"compléter","prompt":"Complète le filtre pour conserver les lignes dont la clé <code>'disponible'</code> vaut vrai.","starter":"def disponibles(table):\n    return [ligne for ligne in table if ____________]","tests":[{"label":"filtre","expr":"disponibles([{'nom':'A','disponible':True},{'nom':'B','disponible':False}]) == [{'nom':'A','disponible':True}]"}],"hints":["La condition est ligne['disponible']."],"solution":"def disponibles(table):\n    return [ligne for ligne in table if ligne['disponible']]","tags":["table","filtrage","compréhension"]},{"id":"P8-X2","moduleId":"P8","title":"Trouver un stand","level":1,"kind":"écrire","prompt":"Écris <code>stand_par_nom(table, nom)</code> qui renvoie la première ligne dont <code>'nom'</code> correspond, sinon <code>None</code>.","starter":"def stand_par_nom(table, nom):\n    pass","tests":[{"label":"trouvé","expr":"stand_par_nom([{'nom':'A','zone':1},{'nom':'B','zone':2}],'B') == {'nom':'B','zone':2}"},{"label":"absent","expr":"stand_par_nom([], 'X') is None"}],"hints":["Parcours ligne par ligne et retourne immédiatement quand le nom correspond."],"solution":"def stand_par_nom(table, nom):\n    for ligne in table:\n        if ligne['nom'] == nom:\n            return ligne\n    return None","tags":["table","recherche","événement"]},{"id":"P8-X3","moduleId":"P8","title":"Déboguer un filtre","level":2,"kind":"déboguer","prompt":"La fonction doit créer une nouvelle table avec les notes strictement supérieures au seuil, mais elle conserve actuellement les mauvaises lignes. Corrige-la.","starter":"def au_dessus(table, seuil):\n    resultat = []\n    for ligne in table:\n        if ligne['note'] <= seuil:\n            resultat.append(ligne)\n    return resultat","tests":[{"label":"strictement supérieur","expr":"au_dessus([{'note':8},{'note':12},{'note':10}],10) == [{'note':12}]"},{"label":"vide","expr":"au_dessus([],10) == []"}],"hints":["Le signe de comparaison est inversé.","Le seuil lui-même n’est pas conservé."],"solution":"def au_dessus(table, seuil):\n    resultat = []\n    for ligne in table:\n        if ligne['note'] > seuil:\n            resultat.append(ligne)\n    return resultat","tags":["table","débogage","frontière"]},{"id":"P8-X4","moduleId":"P8","title":"Extraire une colonne","level":2,"kind":"écrire","prompt":"Écris <code>colonne(table, cle)</code> qui renvoie la liste des valeurs associées à la clé, dans l’ordre des lignes.","starter":"def colonne(table, cle):\n    pass","tests":[{"label":"noms","expr":"colonne([{'nom':'Ada','age':17},{'nom':'Alan','age':18}],'nom') == ['Ada','Alan']"},{"label":"vide","expr":"colonne([], 'nom') == []"}],"hints":["Construis une liste avec ligne[cle] pour chaque ligne."],"solution":"def colonne(table, cle):\n    resultat = []\n    for ligne in table:\n        resultat.append(ligne[cle])\n    return resultat","tags":["table","colonne","liste"]},{"id":"P8-X5","moduleId":"P8","title":"Associer badges et élèves","level":3,"kind":"transfert","prompt":"Deux tables utilisent la clé <code>id</code>. <code>badges_eleves(eleves, badges)</code> renvoie les tuples <code>(nom, badge)</code> lorsque l’id est présent dans les deux tables.","starter":"def badges_eleves(eleves, badges):\n    pass","tests":[{"label":"jointure","expr":"badges_eleves([{'id':1,'nom':'Ada'},{'id':2,'nom':'Alan'}],[{'id':2,'badge':'or'},{'id':1,'badge':'argent'}]) == [('Ada','argent'),('Alan','or')]"},{"label":"id manquant","expr":"badges_eleves([{'id':1,'nom':'Ada'}],[]) == []"}],"hints":["Pour chaque élève, cherche le badge de même id.","Deux boucles imbriquées sont suffisantes au niveau Première."],"solution":"def badges_eleves(eleves, badges):\n    resultat = []\n    for e in eleves:\n        for b in badges:\n            if e['id'] == b['id']:\n                resultat.append((e['nom'], b['badge']))\n    return resultat","tags":["fusion de tables","clé","transfert"]},{"id":"P9-X1","moduleId":"P9","title":"Recherche séquentielle","level":1,"kind":"compléter","prompt":"Complète <code>contient(tab, x)</code> sans utiliser <code>in</code>.","starter":"def contient(tab, x):\n    for valeur in tab:\n        if ____________:\n            return True\n    return False","tests":[{"label":"présent","expr":"contient([3,8,1],8) is True"},{"label":"absent","expr":"contient([3,8,1],9) is False"}],"hints":["Compare valeur et x."],"solution":"def contient(tab, x):\n    for valeur in tab:\n        if valeur == x:\n            return True\n    return False","tags":["recherche","linéaire","compléter"]},{"id":"P9-X2","moduleId":"P9","title":"Déboguer la dichotomie","level":2,"kind":"déboguer","prompt":"La recherche dichotomique peut boucler car les bornes ne progressent pas correctement. Corrige-la.","starter":"def contient_dicho(tab, x):\n    g = 0\n    d = len(tab) - 1\n    while g <= d:\n        m = (g + d) // 2\n        if tab[m] == x:\n            return True\n        elif tab[m] < x:\n            g = m\n        else:\n            d = m\n    return False","tests":[{"label":"présent","expr":"contient_dicho([1,4,7,9],9) is True"},{"label":"absent","expr":"contient_dicho([1,4,7,9],8) is False"},{"label":"premier","expr":"contient_dicho([1,4,7,9],1) is True"}],"hints":["Après avoir testé m, il faut exclure m.","Utilise m+1 ou m-1."],"solution":"def contient_dicho(tab, x):\n    g = 0\n    d = len(tab) - 1\n    while g <= d:\n        m = (g + d) // 2\n        if tab[m] == x:\n            return True\n        elif tab[m] < x:\n            g = m + 1\n        else:\n            d = m - 1\n    return False","tags":["dichotomie","débogage","terminaison"]},{"id":"P9-X3","moduleId":"P9","title":"Tri d’une playlist par durée","level":2,"kind":"écrire","prompt":"Écris <code>tri_durees(tab)</code> qui renvoie une copie triée par ordre croissant avec un tri par insertion. N’utilise pas <code>sorted</code> ni <code>sort</code>.","starter":"def tri_durees(tab):\n    t = list(tab)\n    # tri par insertion\n    pass","tests":[{"label":"tri","expr":"tri_durees([210,90,150]) == [90,150,210]"},{"label":"original préservé","expr":"(lambda x: (tri_durees(x),x)[1])([2,1]) == [2,1]"}],"hints":["À partir de l’indice 1, décale vers la gauche tant que l’élément précédent est plus grand.","Échange les voisins ou mémorise la valeur à insérer."],"solution":"def tri_durees(tab):\n    t = list(tab)\n    for i in range(1, len(t)):\n        valeur = t[i]\n        j = i\n        while j > 0 and t[j-1] > valeur:\n            t[j] = t[j-1]\n            j -= 1\n        t[j] = valeur\n    return t","tags":["tri insertion","playlist","copie"]},{"id":"P9-X4","moduleId":"P9","title":"Vérifier un tri","level":2,"kind":"écrire","prompt":"Écris <code>est_trie(tab)</code> qui renvoie vrai si la liste est croissante au sens large.","starter":"def est_trie(tab):\n    pass","tests":[{"label":"croissante","expr":"est_trie([1,2,2,5]) is True"},{"label":"descente","expr":"est_trie([1,3,2]) is False"},{"label":"vide","expr":"est_trie([]) is True"}],"hints":["Compare chaque élément à son précédent à partir de l’indice 1."],"solution":"def est_trie(tab):\n    for i in range(1, len(tab)):\n        if tab[i] < tab[i-1]:\n            return False\n    return True","tags":["tri","invariant","liste"]},{"id":"P9-X5","moduleId":"P9","title":"Rendu de monnaie glouton","level":3,"kind":"transfert","prompt":"Avec les pièces <code>[50,20,10,5,2,1]</code>, écris <code>rendu(montant)</code> qui renvoie une liste de pièces en prenant toujours la plus grande possible jusqu’à atteindre 0.","starter":"def rendu(montant):\n    pieces = [50,20,10,5,2,1]\n    pass","tests":[{"label":"87","expr":"rendu(87) == [50,20,10,5,2]"},{"label":"0","expr":"rendu(0) == []"},{"label":"6","expr":"rendu(6) == [5,1]"}],"hints":["Parcours les valeurs de pièces de la plus grande à la plus petite.","Tant que la pièce tient dans le montant restant, ajoute-la et soustrais-la."],"solution":"def rendu(montant):\n    pieces = [50,20,10,5,2,1]\n    resultat = []\n    for piece in pieces:\n        while montant >= piece:\n            resultat.append(piece)\n            montant -= piece\n    return resultat","tags":["glouton","monnaie","while"]},{"id":"T1-X1","moduleId":"T1","title":"Répéter un symbole","level":1,"kind":"compléter","prompt":"Complète récursivement <code>repete(c, n)</code> pour renvoyer le caractère <code>c</code> répété n fois.","starter":"def repete(c, n):\n    if n == 0:\n        return ''\n    return ____________","tests":[{"label":"trois","expr":"repete('x',3) == 'xxx'"},{"label":"zéro","expr":"repete('a',0) == ''"}],"hints":["Ajoute c devant le résultat pour n-1."],"solution":"def repete(c, n):\n    if n == 0:\n        return ''\n    return c + repete(c, n-1)","tags":["récursivité","chaîne","cas de base"]},{"id":"T1-X2","moduleId":"T1","title":"Longueur récursive","level":1,"kind":"écrire","prompt":"Écris <code>longueur(tab, i=0)</code> récursivement, sans <code>len</code> dans le calcul de la réponse. Le paramètre i représente l’indice courant ; tu peux seulement comparer i à la taille via un test donné dans le code de départ.","starter":"def longueur(tab, i=0):\n    if i == len(tab):\n        return 0\n    pass","tests":[{"label":"trois","expr":"longueur([4,8,2]) == 3"},{"label":"vide","expr":"longueur([]) == 0"}],"hints":["Chaque élément courant compte pour 1.","Ajoute 1 à longueur(tab, i+1)."],"solution":"def longueur(tab, i=0):\n    if i == len(tab):\n        return 0\n    return 1 + longueur(tab, i+1)","tags":["récursivité","liste"]},{"id":"T1-X3","moduleId":"T1","title":"Déboguer la descente","level":2,"kind":"déboguer","prompt":"La fonction doit calculer <code>1 + 2 + ... + n</code>, mais elle ne termine pas. Corrige-la.","starter":"def somme_n(n):\n    if n == 0:\n        return 0\n    return n + somme_n(n + 1)","tests":[{"label":"0","expr":"somme_n(0) == 0"},{"label":"4","expr":"somme_n(4) == 10"}],"hints":["Le problème transmis doit devenir plus petit.","Remplace n+1 par n-1."],"solution":"def somme_n(n):\n    if n == 0:\n        return 0\n    return n + somme_n(n - 1)","tags":["récursivité","débogage","terminaison"]},{"id":"T1-X4","moduleId":"T1","title":"Palindrome récursif sans slice","level":2,"kind":"écrire","prompt":"Écris <code>palindrome(texte, g=0, d=None)</code> récursivement en comparant les deux extrémités, sans slice.","starter":"def palindrome(texte, g=0, d=None):\n    if d is None:\n        d = len(texte) - 1\n    pass","tests":[{"label":"kayak","expr":"palindrome('kayak') is True"},{"label":"python","expr":"palindrome('python') is False"},{"label":"vide","expr":"palindrome('') is True"}],"hints":["Quand g >= d, il ne reste rien à contredire.","Si les caractères diffèrent, retourne False ; sinon rapproche les indices."],"solution":"def palindrome(texte, g=0, d=None):\n    if d is None:\n        d = len(texte) - 1\n    if g >= d:\n        return True\n    if texte[g] != texte[d]:\n        return False\n    return palindrome(texte, g+1, d-1)","tags":["récursivité","chaîne","indices"]},{"id":"T1-X5","moduleId":"T1","title":"Nombre de dossiers","level":3,"kind":"transfert","prompt":"Un dossier est représenté par un dictionnaire <code>{'nom': ..., 'enfants': [...]}</code>. Écris récursivement <code>nb_dossiers(dossier)</code> qui compte le dossier courant et tous ses descendants.","starter":"def nb_dossiers(dossier):\n    pass","tests":[{"label":"feuille","expr":"nb_dossiers({'nom':'A','enfants':[]}) == 1"},{"label":"arbre","expr":"nb_dossiers({'nom':'A','enfants':[{'nom':'B','enfants':[]},{'nom':'C','enfants':[{'nom':'D','enfants':[]}]}]}) == 4"}],"hints":["Commence le compteur à 1 pour le dossier courant.","Ajoute récursivement le nombre de chaque enfant."],"solution":"def nb_dossiers(dossier):\n    total = 1\n    for enfant in dossier['enfants']:\n        total += nb_dossiers(enfant)\n    return total","tags":["récursivité","arbre","fichiers"]},{"id":"T2-X1","moduleId":"T2","title":"Avatar","level":1,"kind":"compléter","prompt":"Complète la classe <code>Avatar</code> avec les attributs <code>nom</code> et <code>energie</code>.","starter":"class Avatar:\n    def __init__(self, nom, energie):\n        ____________\n        ____________","tests":[{"label":"nom","expr":"Avatar('Ada',10).nom == 'Ada'"},{"label":"energie","expr":"Avatar('Ada',10).energie == 10"}],"hints":["Affecte les paramètres aux attributs self.nom et self.energie."],"solution":"class Avatar:\n    def __init__(self, nom, energie):\n        self.nom = nom\n        self.energie = energie","tags":["POO","constructeur","avatar"]},{"id":"T2-X2","moduleId":"T2","title":"Playlist","level":2,"kind":"écrire","prompt":"Crée une classe <code>Playlist</code> avec un attribut liste <code>titres</code>, une méthode <code>ajouter(titre)</code> et une méthode <code>nb_titres()</code>.","starter":"class Playlist:\n    def __init__(self):\n        pass\n\n    def ajouter(self, titre):\n        pass\n\n    def nb_titres(self):\n        pass","tests":[{"label":"vide","expr":"Playlist().nb_titres() == 0"},{"label":"ajouts","expr":"(lambda p: (p.ajouter('A'),p.ajouter('B'),p.nb_titres())[2])(Playlist()) == 2"}],"hints":["Initialise self.titres à [].","append ajoute un titre ; len donne le nombre."],"solution":"class Playlist:\n    def __init__(self):\n        self.titres = []\n\n    def ajouter(self, titre):\n        self.titres.append(titre)\n\n    def nb_titres(self):\n        return len(self.titres)","tags":["POO","liste","musique"]},{"id":"T2-X3","moduleId":"T2","title":"Déboguer les attributs","level":2,"kind":"déboguer","prompt":"Deux objets <code>Compteur</code> doivent être indépendants, mais la liste est actuellement partagée. Corrige la classe.","starter":"class Compteur:\n    valeurs = []\n    def ajouter(self, x):\n        self.valeurs.append(x)","tests":[{"label":"indépendance","expr":"(lambda a,b: (a.ajouter(1), len(a.valeurs)==1 and len(b.valeurs)==0)[1])(Compteur(),Compteur()) is True"}],"hints":["Une liste de classe est partagée par toutes les instances.","Crée self.valeurs = [] dans __init__."],"solution":"class Compteur:\n    def __init__(self):\n        self.valeurs = []\n    def ajouter(self, x):\n        self.valeurs.append(x)","tags":["POO","attribut instance","débogage"]},{"id":"T2-X4","moduleId":"T2","title":"Capteur","level":2,"kind":"écrire","prompt":"Crée <code>Capteur(nom)</code> avec une liste <code>mesures</code>, une méthode <code>ajouter(valeur)</code> et <code>derniere()</code> qui renvoie la dernière mesure ou <code>None</code> si aucune.","starter":"class Capteur:\n    pass","tests":[{"label":"aucune","expr":"Capteur('T').derniere() is None"},{"label":"dernière","expr":"(lambda c: (c.ajouter(3),c.ajouter(8),c.derniere())[2])(Capteur('T')) == 8"}],"hints":["Teste len(self.mesures) == 0.","La dernière mesure est self.mesures[len(self.mesures)-1]."],"solution":"class Capteur:\n    def __init__(self, nom):\n        self.nom = nom\n        self.mesures = []\n    def ajouter(self, valeur):\n        self.mesures.append(valeur)\n    def derniere(self):\n        if len(self.mesures) == 0:\n            return None\n        return self.mesures[len(self.mesures)-1]","tags":["POO","capteur","liste"]},{"id":"T2-X5","moduleId":"T2","title":"Match entre joueurs","level":3,"kind":"transfert","prompt":"Crée une classe <code>Joueur</code> avec <code>nom</code>, <code>score</code> et une méthode <code>gagne_contre(autre)</code> qui renvoie vrai si son score est strictement supérieur à celui de l’autre joueur.","starter":"class Joueur:\n    pass","tests":[{"label":"gagne","expr":"Joueur('A',10).gagne_contre(Joueur('B',8)) is True"},{"label":"égalité non victoire","expr":"Joueur('A',10).gagne_contre(Joueur('B',10)) is False"}],"hints":["Stocke nom et score dans __init__.","Compare self.score et autre.score."],"solution":"class Joueur:\n    def __init__(self, nom, score):\n        self.nom = nom\n        self.score = score\n    def gagne_contre(self, autre):\n        return self.score > autre.score","tags":["POO","objets","jeu"]},{"id":"T3-X1","moduleId":"T3","title":"Historique retour arrière","level":1,"kind":"écrire","prompt":"Écris <code>dernier(historique)</code> qui retire et renvoie la dernière page d’une liste utilisée comme pile. La liste est non vide.","starter":"def dernier(historique):\n    pass","tests":[{"label":"sommet","expr":"dernier(['a','b','c']) == 'c'"}],"hints":["pop() sans argument retire en fin."],"solution":"def dernier(historique):\n    return historique.pop()","tags":["pile","LIFO","navigation"]},{"id":"T3-X2","moduleId":"T3","title":"File d’attente","level":1,"kind":"compléter","prompt":"Complète <code>servir(file)</code> pour retirer le premier élément de la liste représentant une file simple.","starter":"def servir(file):\n    assert len(file) > 0\n    return file.pop(____)","tests":[{"label":"FIFO","expr":"servir(['Ada','Alan','Grace']) == 'Ada'"},{"label":"vide refusé","expr":"servir([])","raises":"AssertionError"}],"hints":["Le premier élément est d’indice 0."],"solution":"def servir(file):\n    assert len(file) > 0\n    return file.pop(0)","tags":["file","FIFO","compléter"]},{"id":"T3-X3","moduleId":"T3","title":"Déboguer les parenthèses","level":2,"kind":"déboguer","prompt":"La fonction considère à tort <code>'(()'</code> comme équilibré. Corrige-la.","starter":"def equilibrees(texte):\n    pile = []\n    for c in texte:\n        if c == '(':\n            pile.append(c)\n        elif c == ')' and pile:\n            pile.pop()\n    return True","tests":[{"label":"ok","expr":"equilibrees('(())') is True"},{"label":"ouverte restante","expr":"equilibrees('(()') is False"},{"label":"fermeture trop tôt","expr":"equilibrees(')(') is False"}],"hints":["Une fermeture avec pile vide doit renvoyer False.","À la fin, la pile doit être vide."],"solution":"def equilibrees(texte):\n    pile = []\n    for c in texte:\n        if c == '(':\n            pile.append(c)\n        elif c == ')':\n            if len(pile) == 0:\n                return False\n            pile.pop()\n    return len(pile) == 0","tags":["pile","débogage","parenthèses"]},{"id":"T3-X4","moduleId":"T3","title":"Annuler une action","level":2,"kind":"écrire","prompt":"Une pile contient des états successifs. Écris <code>annule(etats)</code> qui retire le dernier état si au moins deux états existent, puis renvoie le nouvel état courant. Avec un seul état, il reste inchangé.","starter":"def annule(etats):\n    pass","tests":[{"label":"annulation","expr":"annule(['v1','v2','v3']) == 'v2'"},{"label":"état initial","expr":"annule(['v1']) == 'v1'"}],"hints":["Retire seulement si len(etats) > 1.","Le courant est ensuite le dernier élément."],"solution":"def annule(etats):\n    assert len(etats) > 0\n    if len(etats) > 1:\n        etats.pop()\n    return etats[len(etats)-1]","tags":["pile","undo","interface"]},{"id":"T3-X5","moduleId":"T3","title":"File de tickets avec deux piles","level":3,"kind":"transfert","prompt":"Écris une classe <code>FileTickets</code> utilisant deux listes <code>entree</code> et <code>sortie</code>. <code>ajouter</code> empile dans entree ; <code>retirer</code> respecte FIFO.","starter":"class FileTickets:\n    def __init__(self):\n        self.entree = []\n        self.sortie = []\n    def ajouter(self, ticket):\n        pass\n    def retirer(self):\n        pass","tests":[{"label":"FIFO","expr":"(lambda f: (f.ajouter('A'),f.ajouter('B'),f.retirer(),f.retirer())[3])(FileTickets()) == 'B'"}],"hints":["Si sortie est vide, transfère tous les éléments de entree avec pop/append.","Puis retire depuis sortie."],"solution":"class FileTickets:\n    def __init__(self):\n        self.entree = []\n        self.sortie = []\n    def ajouter(self, ticket):\n        self.entree.append(ticket)\n    def retirer(self):\n        if len(self.sortie) == 0:\n            while len(self.entree) > 0:\n                self.sortie.append(self.entree.pop())\n        return self.sortie.pop()","tags":["file","deux piles","tickets"]},{"id":"T4-X1","moduleId":"T4","title":"Compter les feuilles","level":1,"kind":"écrire","prompt":"Avec <code>Noeud</code>, écris récursivement <code>feuilles(a)</code> qui compte les feuilles d’un arbre binaire.","starter":"class Noeud:\n       def __init__(self, valeur, gauche=None, droite=None):\n           self.valeur = valeur\n           self.gauche = gauche\n           self.droite = droite\n\ndef feuilles(a):\n       pass","tests":[{"label":"vide","expr":"feuilles(None) == 0"},{"label":"une feuille","expr":"feuilles(Noeud(1)) == 1"},{"label":"deux feuilles","expr":"feuilles(Noeud(1,Noeud(2),Noeud(3))) == 2"}],"hints":["Vide → 0.","Si gauche et droite sont None, le nœud courant est une feuille.","Sinon additionne les feuilles des sous-arbres."],"solution":"class Noeud:\n       def __init__(self, valeur, gauche=None, droite=None):\n           self.valeur = valeur\n           self.gauche = gauche\n           self.droite = droite\n\ndef feuilles(a):\n       if a is None:\n           return 0\n       if a.gauche is None and a.droite is None:\n           return 1\n       return feuilles(a.gauche) + feuilles(a.droite)","tags":["arbre","récursivité","feuille"]},{"id":"T4-X2","moduleId":"T4","title":"Déboguer la hauteur","level":2,"kind":"déboguer","prompt":"La hauteur est ici définie comme le nombre de nœuds du plus long chemin racine-feuille ; l’arbre vide a hauteur 0. Corrige la fonction.","starter":"class Noeud:\n       def __init__(self, valeur, gauche=None, droite=None):\n           self.valeur = valeur\n           self.gauche = gauche\n           self.droite = droite\n\ndef hauteur(a):\n       if a is None:\n           return 1\n       return max(hauteur(a.gauche), hauteur(a.droite))","tests":[{"label":"vide","expr":"hauteur(None) == 0"},{"label":"un","expr":"hauteur(Noeud(1)) == 1"},{"label":"chaîne","expr":"hauteur(Noeud(1,Noeud(2,Noeud(3)))) == 3"}],"hints":["Vide → 0.","Un nœud courant ajoute 1 à la hauteur maximale des deux sous-arbres."],"solution":"class Noeud:\n       def __init__(self, valeur, gauche=None, droite=None):\n           self.valeur = valeur\n           self.gauche = gauche\n           self.droite = droite\n\ndef hauteur(a):\n       if a is None:\n           return 0\n       hg = hauteur(a.gauche)\n       hd = hauteur(a.droite)\n       return 1 + max(hg, hd)","tags":["arbre","hauteur","débogage"]},{"id":"T4-X3","moduleId":"T4","title":"Parcours préfixe","level":2,"kind":"compléter","prompt":"Complète <code>prefixe(a)</code> pour renvoyer la liste des valeurs en ordre nœud-gauche-droite.","starter":"class Noeud:\n       def __init__(self, valeur, gauche=None, droite=None):\n           self.valeur = valeur\n           self.gauche = gauche\n           self.droite = droite\n\ndef prefixe(a):\n       if a is None:\n           return []\n       return ____________","tests":[{"label":"ordre","expr":"prefixe(Noeud('A',Noeud('B'),Noeud('C'))) == ['A','B','C']"}],"hints":["Commence par [a.valeur].","Puis concatène les parcours gauche et droite."],"solution":"class Noeud:\n       def __init__(self, valeur, gauche=None, droite=None):\n           self.valeur = valeur\n           self.gauche = gauche\n           self.droite = droite\n\ndef prefixe(a):\n       if a is None:\n           return []\n       return [a.valeur] + prefixe(a.gauche) + prefixe(a.droite)","tags":["arbre","parcours","préfixe"]},{"id":"T4-X4","moduleId":"T4","title":"Minimum d’un ABR","level":2,"kind":"écrire","prompt":"Dans un ABR non vide, le minimum est le nœud le plus à gauche. Écris <code>minimum_abr(a)</code> sans construire de liste.","starter":"class Noeud:\n    def __init__(self, valeur, gauche=None, droite=None):\n        self.valeur = valeur\n        self.gauche = gauche\n        self.droite = droite\n\ndef minimum_abr(a):\n       pass","tests":[{"label":"minimum","expr":"minimum_abr(Noeud(8,Noeud(3,Noeud(1),Noeud(6)),Noeud(12))) == 1"},{"label":"racine seule","expr":"minimum_abr(Noeud(5)) == 5"}],"hints":["Tant qu’il existe un fils gauche, avance vers lui.","Retourne la valeur du dernier nœud atteint."],"solution":"class Noeud:\n    def __init__(self, valeur, gauche=None, droite=None):\n        self.valeur = valeur\n        self.gauche = gauche\n        self.droite = droite\n\ndef minimum_abr(a):\n       assert a is not None\n       while a.gauche is not None:\n           a = a.gauche\n       return a.valeur","tags":["ABR","while","ordre"]},{"id":"T4-X5","moduleId":"T4","title":"Insérer dans un ABR","level":3,"kind":"transfert","prompt":"Écris récursivement <code>insere(a, x)</code> qui insère x dans un ABR ; on suppose x absent. La fonction renvoie la racine.","starter":"class Noeud:\n       def __init__(self, valeur, gauche=None, droite=None):\n           self.valeur = valeur\n           self.gauche = gauche\n           self.droite = droite\n\ndef insere(a, x):\n       pass","tests":[{"label":"dans vide","expr":"insere(None,5).valeur == 5"},{"label":"à gauche","expr":"(lambda a: (insere(a,3), a.gauche.valeur)[1])(Noeud(5)) == 3"},{"label":"à droite","expr":"(lambda a: (insere(a,8), a.droite.valeur)[1])(Noeud(5)) == 8"}],"hints":["Vide → nouveau Noeud(x).","Sinon choisis gauche ou droite et réaffecte le sous-arbre retourné."],"solution":"class Noeud:\n       def __init__(self, valeur, gauche=None, droite=None):\n           self.valeur = valeur\n           self.gauche = gauche\n           self.droite = droite\n\ndef insere(a, x):\n       if a is None:\n           return Noeud(x)\n       if x < a.valeur:\n           a.gauche = insere(a.gauche, x)\n       else:\n           a.droite = insere(a.droite, x)\n       return a","tags":["ABR","insertion","récursivité"]},{"id":"T5-X1","moduleId":"T5","title":"Voisins d’un sommet","level":1,"kind":"compléter","prompt":"Complète <code>voisins(g, s)</code> pour renvoyer une copie de la liste des voisins de s.","starter":"def voisins(g, s):\n    return list(____________)","tests":[{"label":"voisins","expr":"voisins({'A':['B','C']},'A') == ['B','C']"}],"hints":["Accède à g[s]."],"solution":"def voisins(g, s):\n    return list(g[s])","tags":["graphe","dictionnaire","liste"]},{"id":"T5-X2","moduleId":"T5","title":"Sommets isolés","level":2,"kind":"écrire","prompt":"Pour un graphe non orienté représenté par dictionnaire de voisins, écris <code>isoles(g)</code> qui renvoie l’ensemble des sommets sans voisin.","starter":"def isoles(g):\n    pass","tests":[{"label":"isolés","expr":"isoles({'A':['B'],'B':['A'],'C':[]}) == {'C'}"},{"label":"aucun","expr":"isoles({'A':['B'],'B':['A']}) == set()"}],"hints":["Un sommet est isolé si len(g[s]) == 0."],"solution":"def isoles(g):\n    resultat = set()\n    for s in g:\n        if len(g[s]) == 0:\n            resultat.add(s)\n    return resultat","tags":["graphe","ensemble","degré"]},{"id":"T5-X3","moduleId":"T5","title":"Déboguer le DFS","level":2,"kind":"déboguer","prompt":"Le DFS ci-dessous peut revisiter indéfiniment des sommets dans un cycle. Corrige-le en utilisant <code>visites</code>.","starter":"def dfs(g, depart):\n    pile = [depart]\n    visites = set()\n    while pile:\n        s = pile.pop()\n        for v in g[s]:\n            pile.append(v)\n    return visites","tests":[{"label":"cycle","expr":"dfs({'A':['B'],'B':['A','C'],'C':['B']},'A') == {'A','B','C'}"}],"hints":["Quand tu dépiles un sommet nouveau, ajoute-le à visites.","N’empile que les voisins pas encore visités."],"solution":"def dfs(g, depart):\n    pile = [depart]\n    visites = set()\n    while pile:\n        s = pile.pop()\n        if s not in visites:\n            visites.add(s)\n            for v in g[s]:\n                if v not in visites:\n                    pile.append(v)\n    return visites","tags":["DFS","cycle","débogage"]},{"id":"T5-X4","moduleId":"T5","title":"Existe-t-il un chemin ?","level":2,"kind":"écrire","prompt":"Écris <code>chemin_existe(g, depart, arrivee)</code> avec un parcours en largeur ou profondeur.","starter":"def chemin_existe(g, depart, arrivee):\n    pass","tests":[{"label":"oui","expr":"chemin_existe({'A':['B'],'B':['C'],'C':[]},'A','C') is True"},{"label":"non","expr":"chemin_existe({'A':[],'B':[]},'A','B') is False"},{"label":"même sommet","expr":"chemin_existe({'A':[]},'A','A') is True"}],"hints":["Parcours les sommets accessibles à partir de depart.","Retourne True lorsque arrivee est rencontré."],"solution":"def chemin_existe(g, depart, arrivee):\n    visites = set()\n    pile = [depart]\n    while pile:\n        s = pile.pop()\n        if s == arrivee:\n            return True\n        if s not in visites:\n            visites.add(s)\n            for v in g[s]:\n                if v not in visites:\n                    pile.append(v)\n    return False","tags":["graphe","chemin","DFS"]},{"id":"T5-X5","moduleId":"T5","title":"Itinéraire minimal","level":3,"kind":"transfert","prompt":"Écris <code>itineraire(g, depart, arrivee)</code> qui renvoie un plus court chemin sous forme de liste de sommets dans un graphe non pondéré, ou <code>None</code> si impossible.","starter":"def itineraire(g, depart, arrivee):\n    pass","tests":[{"label":"chemin court","expr":"itineraire({'A':['B','C'],'B':['D'],'C':['D'],'D':[]},'A','D') in (['A','B','D'], ['A','C','D'])"},{"label":"même sommet","expr":"itineraire({'A':[]},'A','A') == ['A']"},{"label":"impossible","expr":"itineraire({'A':[],'B':[]},'A','B') is None"}],"hints":["BFS garantit le nombre minimal d’arêtes.","Tu peux stocker dans la file des couples (sommet, chemin_jusque_la)."],"solution":"def itineraire(g, depart, arrivee):\n    file = [(depart, [depart])]\n    visites = {depart}\n    while file:\n        s, chemin = file.pop(0)\n        if s == arrivee:\n            return chemin\n        for v in g[s]:\n            if v not in visites:\n                visites.add(v)\n                file.append((v, chemin + [v]))\n    return None","tags":["BFS","plus court chemin","transfert"]},{"id":"T6-X1","moduleId":"T6","title":"SELECT ciblé","level":1,"kind":"compléter","prompt":"Complète la chaîne SQL pour sélectionner les colonnes <code>nom</code> et <code>score</code> de la table <code>joueur</code>.","starter":"def requete():\n    return 'SELECT __________ FROM joueur'","tests":[{"label":"requête","expr":"requete().strip().upper() == 'SELECT NOM, SCORE FROM JOUEUR'"}],"hints":["La partie manquante est nom, score."],"solution":"def requete():\n    return 'SELECT nom, score FROM joueur'","tags":["SQL","SELECT","chaîne"]},{"id":"T6-X2","moduleId":"T6","title":"Filtrer un score","level":1,"kind":"écrire","prompt":"Écris <code>requete_score()</code> qui renvoie <code>SELECT nom FROM joueur WHERE score >= ?</code>.","starter":"def requete_score():\n    pass","tests":[{"label":"requête paramétrée","expr":"requete_score().strip().upper() == 'SELECT NOM FROM JOUEUR WHERE SCORE >= ?'"}],"hints":["Le ? représente un paramètre transmis séparément."],"solution":"def requete_score():\n    return 'SELECT nom FROM joueur WHERE score >= ?'","tags":["SQL","WHERE","paramètre"]},{"id":"T6-X3","moduleId":"T6","title":"Déboguer la requête paramétrée","level":2,"kind":"déboguer","prompt":"La fonction construit dangereusement la requête en concaténant une saisie. Corrige-la pour utiliser un paramètre <code>?</code>.","starter":"def cherche_nom(cur, nom):\n    cur.execute(\"SELECT id FROM joueur WHERE nom = '\" + nom + \"'\")\n    return cur.fetchone()","tests":[{"label":"appel sûr","expr":"(lambda c: (setattr(c.fetchone,'return_value',(3,)), cherche_nom(c,'Ada') == (3,) and (c.execute.assert_called_once_with('SELECT id FROM joueur WHERE nom = ?', ('Ada',)) is None))[1])(__import__('unittest.mock',fromlist=['Mock']).Mock())"}],"hints":["La chaîne SQL contient WHERE nom = ?.","Passe (nom,) comme second argument de execute."],"solution":"def cherche_nom(cur, nom):\n    cur.execute('SELECT id FROM joueur WHERE nom = ?', (nom,))\n    return cur.fetchone()","tags":["SQL","sécurité","paramétrage"]},{"id":"T6-X4","moduleId":"T6","title":"Jointure de playlists","level":2,"kind":"écrire","prompt":"Écris <code>requete_playlist()</code> qui renvoie une requête sélectionnant <code>morceau.titre</code> et <code>artiste.nom</code>, avec <code>JOIN artiste ON morceau.artiste_id = artiste.id</code>.","starter":"def requete_playlist():\n    pass","tests":[{"label":"SELECT","expr":"'SELECT MORCEAU.TITRE, ARTISTE.NOM' in requete_playlist().upper()"},{"label":"JOIN","expr":"'JOIN ARTISTE ON MORCEAU.ARTISTE_ID = ARTISTE.ID' in requete_playlist().upper()"}],"hints":["FROM morceau JOIN artiste ON ..."],"solution":"def requete_playlist():\n    return 'SELECT morceau.titre, artiste.nom FROM morceau JOIN artiste ON morceau.artiste_id = artiste.id'","tags":["SQL","JOIN","musique"]},{"id":"T6-X5","moduleId":"T6","title":"Mettre à jour un statut","level":3,"kind":"transfert","prompt":"Écris <code>ferme_ticket(cur, identifiant)</code> qui exécute <code>UPDATE ticket SET statut = ? WHERE id = ?</code> avec les paramètres <code>('ferme', identifiant)</code>.","starter":"def ferme_ticket(cur, identifiant):\n    pass","tests":[{"label":"UPDATE paramétré","expr":"(lambda c: (ferme_ticket(c,7), c.execute.assert_called_once_with('UPDATE ticket SET statut = ? WHERE id = ?', ('ferme',7)) is None)[1])(__import__('unittest.mock',fromlist=['Mock']).Mock())"}],"hints":["Le premier paramètre remplace le premier ?, le second remplace le second.","Il n’est pas demandé ici de commit."],"solution":"def ferme_ticket(cur, identifiant):\n    cur.execute('UPDATE ticket SET statut = ? WHERE id = ?', ('ferme', identifiant))","tags":["SQL","UPDATE","ticket"]},{"id":"T7-X1","moduleId":"T7","title":"Corriger un effet de bord","level":1,"kind":"déboguer","prompt":"La fonction doit renvoyer une liste enrichie sans modifier l’originale. Corrige-la.","starter":"def ajoute_fin(tab, x):\n    resultat = tab\n    resultat.append(x)\n    return resultat","tests":[{"label":"résultat","expr":"ajoute_fin([1,2],3) == [1,2,3]"},{"label":"original","expr":"(lambda a: (ajoute_fin(a,3),a)[1])([1,2]) == [1,2]"}],"hints":["Crée une copie avec list(tab)."],"solution":"def ajoute_fin(tab, x):\n    resultat = list(tab)\n    resultat.append(x)\n    return resultat","tags":["bug","mutabilité","copie"]},{"id":"T7-X2","moduleId":"T7","title":"Frontière d’indice","level":1,"kind":"déboguer","prompt":"La fonction doit dire si <code>i</code> est un indice valide de <code>tab</code>. Corrige la borne supérieure.","starter":"def indice_valide(tab, i):\n    return 0 <= i <= len(tab)","tests":[{"label":"premier","expr":"indice_valide([4,5],0) is True"},{"label":"dernier","expr":"indice_valide([4,5],1) is True"},{"label":"len invalide","expr":"indice_valide([4,5],2) is False"}],"hints":["Le dernier indice est len(tab)-1.","Utilise i < len(tab)."],"solution":"def indice_valide(tab, i):\n    return 0 <= i < len(tab)","tags":["bug","frontière","indice"]},{"id":"T7-X3","moduleId":"T7","title":"Mini test de régression","level":2,"kind":"écrire","prompt":"Écris <code>sans_doublons_consecutifs(tab)</code> qui conserve le premier élément de chaque série consécutive identique.","starter":"def sans_doublons_consecutifs(tab):\n    pass","tests":[{"label":"groupes","expr":"sans_doublons_consecutifs([1,1,2,2,2,3,1,1]) == [1,2,3,1]"},{"label":"vide","expr":"sans_doublons_consecutifs([]) == []"}],"hints":["Ajoute un élément s’il est le premier ou différent du dernier ajouté."],"solution":"def sans_doublons_consecutifs(tab):\n    resultat = []\n    for x in tab:\n        if len(resultat) == 0 or x != resultat[len(resultat)-1]:\n            resultat.append(x)\n    return resultat","tags":["tests","liste","régression"]},{"id":"T7-X4","moduleId":"T7","title":"Déboguer un compteur","level":2,"kind":"déboguer","prompt":"Cette fonction compte mal les valeurs strictement positives. Corrige son initialisation et sa condition si nécessaire.","starter":"def nb_positifs(tab):\n    n = 1\n    for x in tab:\n        if x >= 0:\n            n += 1\n    return n","tests":[{"label":"vide","expr":"nb_positifs([]) == 0"},{"label":"zéro non positif strict","expr":"nb_positifs([-1,0,2,4]) == 2"}],"hints":["Un compteur commence généralement à 0.","Strictement positif signifie > 0."],"solution":"def nb_positifs(tab):\n    n = 0\n    for x in tab:\n        if x > 0:\n            n += 1\n    return n","tags":["débogage","compteur","tests"]},{"id":"T7-X5","moduleId":"T7","title":"API de conversion","level":3,"kind":"transfert","prompt":"Écris <code>format_octets(n)</code> qui renvoie <code>'n o'</code> si n < 1000, sinon une chaîne <code>'x.x ko'</code> avec une décimale. La formule donnée est n / 1000.","starter":"def format_octets(n):\n    pass","tests":[{"label":"octets","expr":"format_octets(512) == '512 o'"},{"label":"kilo-octets","expr":"format_octets(1500) == '1.5 ko'"},{"label":"borne","expr":"format_octets(1000) == '1.0 ko'"}],"hints":["Utilise une condition sur n < 1000.","f'{n/1000:.1f} ko' permet une décimale."],"solution":"def format_octets(n):\n    if n < 1000:\n        return f'{n} o'\n    return f'{n/1000:.1f} ko'","tags":["API","formatage","contrat"]},{"id":"T8-X1","moduleId":"T8","title":"Appliquer une transformation","level":1,"kind":"compléter","prompt":"Complète <code>transforme(f, tab)</code> pour appliquer f à chaque élément.","starter":"def transforme(f, tab):\n    resultat = []\n    for x in tab:\n        resultat.append(__________)\n    return resultat","tests":[{"label":"double","expr":"transforme(lambda x:x*2,[1,2,3]) == [2,4,6]"}],"hints":["Appelle f avec x."],"solution":"def transforme(f, tab):\n    resultat = []\n    for x in tab:\n        resultat.append(f(x))\n    return resultat","tags":["fonction paramètre","fonctionnel"]},{"id":"T8-X2","moduleId":"T8","title":"Choisir une stratégie","level":2,"kind":"écrire","prompt":"Écris <code>premier_qui(tab, predicat)</code> qui renvoie le premier élément pour lequel <code>predicat(element)</code> est vrai, ou <code>None</code>.","starter":"def premier_qui(tab, predicat):\n    pass","tests":[{"label":"pair","expr":"premier_qui([1,3,4,6], lambda x:x%2==0) == 4"},{"label":"aucun","expr":"premier_qui([1,3], lambda x:x<0) is None"}],"hints":["Appelle predicat(x) dans une boucle.","Retourne dès la première réussite."],"solution":"def premier_qui(tab, predicat):\n    for x in tab:\n        if predicat(x):\n            return x\n    return None","tags":["fonction paramètre","recherche"]},{"id":"T8-X3","moduleId":"T8","title":"Déboguer la composition","level":2,"kind":"déboguer","prompt":"La fonction <code>compose</code> doit renvoyer une fonction, mais elle appelle h immédiatement. Corrige-la.","starter":"def compose(f, g):\n    def h(x):\n        return f(g(x))\n    return h(0)","tests":[{"label":"fonction retournée","expr":"callable(compose(lambda x:x+1, lambda x:x*2))"},{"label":"résultat","expr":"compose(lambda x:x+1, lambda x:x*2)(5) == 11"}],"hints":["Il faut retourner l’objet fonction h.","N’ajoute pas de parenthèses à h dans le return."],"solution":"def compose(f, g):\n    def h(x):\n        return f(g(x))\n    return h","tags":["fonction","composition","débogage"]},{"id":"T8-X4","moduleId":"T8","title":"Pipeline de texte","level":2,"kind":"transfert","prompt":"Écris <code>pipeline(texte, fonctions)</code> qui applique successivement chaque fonction de la liste au résultat courant.","starter":"def pipeline(texte, fonctions):\n    pass","tests":[{"label":"pipeline","expr":"pipeline(' nsi ', [lambda s:s.strip(), lambda s:s.upper()]) == 'NSI'"},{"label":"aucune fonction","expr":"pipeline('abc',[]) == 'abc'"}],"hints":["Initialise resultat = texte.","Pour chaque f, fais resultat = f(resultat)."],"solution":"def pipeline(texte, fonctions):\n    resultat = texte\n    for f in fonctions:\n        resultat = f(resultat)\n    return resultat","tags":["fonctions","pipeline","texte"]},{"id":"T8-X5","moduleId":"T8","title":"Programme comme donnée","level":3,"kind":"écrire","prompt":"Un petit langage de commandes contient des tuples <code>('AJOUTE', n)</code> et <code>('MULTIPLIE', n)</code>. Écris <code>execute(programme, valeur)</code> qui interprète ces commandes dans l’ordre.","starter":"def execute(programme, valeur):\n    pass","tests":[{"label":"programme","expr":"execute([('AJOUTE',3),('MULTIPLIE',2)],4) == 14"},{"label":"vide","expr":"execute([],7) == 7"}],"hints":["Parcours les tuples commande, n.","Selon commande, modifie valeur."],"solution":"def execute(programme, valeur):\n    for commande, n in programme:\n        if commande == 'AJOUTE':\n            valeur += n\n        elif commande == 'MULTIPLIE':\n            valeur *= n\n    return valeur","tags":["programme donnée","interpréteur","transfert"]},{"id":"T9-X1","moduleId":"T9","title":"Fusion de scores","level":1,"kind":"compléter","prompt":"Complète une étape de fusion de deux listes triées. La fonction fournie doit renvoyer toute la fusion.","starter":"def fusion(a, b):\n    i = j = 0\n    r = []\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            r.append(a[i]); i += 1\n        else:\n            r.append(b[j]); j += 1\n    while i < len(a):\n        r.append(__________); i += 1\n    while j < len(b):\n        r.append(__________); j += 1\n    return r","tests":[{"label":"fusion","expr":"fusion([1,5],[2,3,8]) == [1,2,3,5,8]"}],"hints":["Dans la première boucle restante, ajoute a[i].","Dans la seconde, ajoute b[j]."],"solution":"def fusion(a, b):\n    i = j = 0\n    r = []\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            r.append(a[i]); i += 1\n        else:\n            r.append(b[j]); j += 1\n    while i < len(a):\n        r.append(a[i]); i += 1\n    while j < len(b):\n        r.append(b[j]); j += 1\n    return r","tags":["fusion","listes triées"]},{"id":"T9-X2","moduleId":"T9","title":"Déboguer le cas de base","level":2,"kind":"déboguer","prompt":"Le tri fusion ne termine pas sur une liste vide. Corrige son cas de base.","starter":"def fusion(a,b):\n       r=[]; i=j=0\n       while i<len(a) and j<len(b):\n           if a[i] <= b[j]: r.append(a[i]); i+=1\n           else: r.append(b[j]); j+=1\n       return r + a[i:] + b[j:]\n\ndef tri_fusion(tab):\n       if len(tab) == 1:\n           return list(tab)\n       m = len(tab)//2\n       return fusion(tri_fusion(tab[:m]), tri_fusion(tab[m:]))","tests":[{"label":"vide","expr":"tri_fusion([]) == []"},{"label":"tri","expr":"tri_fusion([3,1,2]) == [1,2,3]"}],"hints":["Le cas de base doit aussi englober la longueur 0.","Utilise <= 1."],"solution":"def fusion(a,b):\n       r=[]; i=j=0\n       while i<len(a) and j<len(b):\n           if a[i] <= b[j]: r.append(a[i]); i+=1\n           else: r.append(b[j]); j+=1\n       return r + a[i:] + b[j:]\n\ndef tri_fusion(tab):\n       if len(tab) <= 1:\n           return list(tab)\n       m = len(tab)//2\n       return fusion(tri_fusion(tab[:m]), tri_fusion(tab[m:]))","tags":["tri fusion","débogage","récursivité"]},{"id":"T9-X3","moduleId":"T9","title":"Classer des latences","level":2,"kind":"transfert","prompt":"Écris <code>classe_latences(tab)</code> qui renvoie une copie triée avec un tri fusion. Utilise tes fonctions <code>fusion</code> et <code>tri_fusion</code> dans la solution.","starter":"def fusion(a, b):\n    pass\n\ndef tri_fusion(tab):\n    pass\n\ndef classe_latences(tab):\n    return tri_fusion(tab)","tests":[{"label":"tri","expr":"classe_latences([42,18,90,25]) == [18,25,42,90]"},{"label":"original","expr":"(lambda x:(classe_latences(x),x)[1])([2,1]) == [2,1]"}],"hints":["Réutilise le schéma diviser/fusionner.","Le cas de base retourne une copie."],"solution":"def fusion(a,b):\n       r=[]; i=j=0\n       while i<len(a) and j<len(b):\n           if a[i] <= b[j]:\n               r.append(a[i]); i+=1\n           else:\n               r.append(b[j]); j+=1\n       return r + a[i:] + b[j:]\n\ndef tri_fusion(tab):\n       if len(tab) <= 1:\n           return list(tab)\n       m=len(tab)//2\n       return fusion(tri_fusion(tab[:m]), tri_fusion(tab[m:]))\n\ndef classe_latences(tab):\n       return tri_fusion(tab)","tags":["tri fusion","réseau","transfert"]},{"id":"T9-X4","moduleId":"T9","title":"Compter par moitié","level":2,"kind":"transfert","prompt":"Écris <code>compte_div(tab, x)</code> récursivement : coupe la liste en deux jusqu’à des listes de taille 0 ou 1, puis additionne les comptes.","starter":"def compte_div(tab, x):\n       pass","tests":[{"label":"occurrences","expr":"compte_div([1,2,1,3,1],1) == 3"},{"label":"vide","expr":"compte_div([],1) == 0"}],"hints":["Cas 0 élément puis cas 1 élément.","Sinon coupe et additionne les deux appels."],"solution":"def compte_div(tab, x):\n       if len(tab) == 0:\n           return 0\n       if len(tab) == 1:\n           return 1 if tab[0] == x else 0\n       m = len(tab) // 2\n       return compte_div(tab[:m], x) + compte_div(tab[m:], x)","tags":["diviser pour régner","transfert"]},{"id":"T9-X5","moduleId":"T9","title":"Dichotomie récursive","level":3,"kind":"écrire","prompt":"La liste est triée. Écris <code>dicho_rec(tab, x, g=0, d=None)</code> qui renvoie un booléen sans boucle.","starter":"def dicho_rec(tab, x, g=0, d=None):\n       if d is None:\n           d = len(tab) - 1\n       pass","tests":[{"label":"présent","expr":"dicho_rec([1,4,7,9,12],9) is True"},{"label":"absent","expr":"dicho_rec([1,4,7,9,12],8) is False"},{"label":"vide","expr":"dicho_rec([],1) is False"}],"hints":["Cas d’arrêt : g > d.","Calcule m, puis choisis un seul intervalle."],"solution":"def dicho_rec(tab, x, g=0, d=None):\n       if d is None:\n           d = len(tab) - 1\n       if g > d:\n           return False\n       m = (g + d) // 2\n       if tab[m] == x:\n           return True\n       if tab[m] < x:\n           return dicho_rec(tab, x, m+1, d)\n       return dicho_rec(tab, x, g, m-1)","tags":["dichotomie","récursivité"]},{"id":"T10-X1","moduleId":"T10","title":"Escalier de jeu","level":1,"kind":"compléter","prompt":"Un personnage avance de 1 ou 2 marches. <code>façons(n)</code> donne le nombre de façons d’atteindre la marche n, avec façons(0)=1 et façons(1)=1. Complète la version bottom-up.","starter":"def facons(n):\n       if n <= 1:\n           return 1\n       dp = [1, 1]\n       for i in range(2, n+1):\n           __________________\n       return dp[n]","tests":[{"label":"0","expr":"facons(0) == 1"},{"label":"1","expr":"facons(1) == 1"},{"label":"5","expr":"facons(5) == 8"}],"hints":["Chaque nouvelle valeur est la somme des deux précédentes."],"solution":"def facons(n):\n       if n <= 1:\n           return 1\n       dp = [1, 1]\n       for i in range(2, n+1):\n           dp.append(dp[i-1] + dp[i-2])\n       return dp[n]","tags":["programmation dynamique","bottom-up"]},{"id":"T10-X2","moduleId":"T10","title":"Score maximal sans voisins","level":2,"kind":"écrire","prompt":"Dans un jeu, deux bonus placés sur des cases voisines ne peuvent pas être pris ensemble. Écris <code>score_max(scores)</code> qui renvoie le meilleur score possible.","starter":"def score_max(scores):\n    pass","tests":[{"label":"vide","expr":"score_max([]) == 0"},{"label":"un bonus","expr":"score_max([7]) == 7"},{"label":"choix","expr":"score_max([4,1,6,3]) == 10"},{"label":"alternance","expr":"score_max([2,7,9,3,1]) == 12"}],"hints":["À chaque position, compare : ne pas prendre le bonus / le prendre en ajoutant le meilleur score deux cases avant.","Deux variables suffisent : meilleur jusqu’à i-2 et meilleur jusqu’à i-1."],"solution":"def score_max(scores):\n    precedent2 = 0\n    precedent1 = 0\n    for score in scores:\n        courant = max(precedent1, precedent2 + score)\n        precedent2 = precedent1\n        precedent1 = courant\n    return precedent1","tags":["programmation dynamique","jeu","transfert"]},{"id":"T10-X3","moduleId":"T10","title":"Déboguer la mémoïsation","level":2,"kind":"déboguer","prompt":"Cette fonction veut calculer le nombre de façons de construire une chaîne de longueur <code>n</code> avec des blocs de taille 1 ou 2, mais elle oublie d’utiliser son mémo. Corrige-la.","starter":"def constructions(n, memo=None):\n    if memo is None:\n        memo = {}\n    if n <= 1:\n        return 1\n    memo[n] = constructions(n-1) + constructions(n-2)\n    return memo[n]","tests":[{"label":"0","expr":"constructions(0) == 1"},{"label":"5","expr":"constructions(5) == 8"},{"label":"20","expr":"constructions(20) == 10946"}],"hints":["Avant de calculer, vérifie si n est déjà dans memo.","Transmets le même dictionnaire memo aux deux appels récursifs."],"solution":"def constructions(n, memo=None):\n    if memo is None:\n        memo = {}\n    if n <= 1:\n        return 1\n    if n in memo:\n        return memo[n]\n    memo[n] = constructions(n-1, memo) + constructions(n-2, memo)\n    return memo[n]","tags":["mémoïsation","débogage"]},{"id":"T10-X4","moduleId":"T10","title":"Sous-titrage : coupures minimales","level":3,"kind":"transfert","prompt":"Une phrase sans espaces doit être découpée en mots connus. Écris <code>nb_mots_min(texte, dictionnaire)</code> qui renvoie le nombre minimal de mots, ou -1 si le découpage est impossible.","starter":"def nb_mots_min(texte, dictionnaire):\n    pass","tests":[{"label":"possible","expr":"nb_mots_min('chatcode', {'chat','code','cha','t'}) == 2"},{"label":"autre découpage","expr":"nb_mots_min('aaaa', {'a','aa'}) == 2"},{"label":"impossible","expr":"nb_mots_min('python', {'py','ton'}) == -1"},{"label":"vide","expr":"nb_mots_min('', {'a'}) == 0"}],"hints":["dp[i] peut représenter le nombre minimal de mots pour former les i premiers caractères.","Pour chaque i, essaie tous les j < i tels que texte[j:i] soit dans le dictionnaire."],"solution":"def nb_mots_min(texte, dictionnaire):\n    inf = len(texte) + 1\n    dp = [0] + [inf] * len(texte)\n    for i in range(1, len(texte) + 1):\n        for j in range(i):\n            if dp[j] != inf and texte[j:i] in dictionnaire:\n                dp[i] = min(dp[i], dp[j] + 1)\n    return -1 if dp[-1] == inf else dp[-1]","tags":["programmation dynamique","chaînes","transfert"]},{"id":"T10-X5","moduleId":"T10","title":"Énergie minimale d’un robot","level":3,"kind":"écrire","prompt":"Un robot traverse des bornes numérotées. Depuis une borne, il peut aller à la suivante ou sauter une borne. Le coût d’un déplacement est la différence absolue d’énergie entre les deux bornes. Écris <code>energie_min(valeurs)</code>.","starter":"def energie_min(valeurs):\n    pass","tests":[{"label":"une borne","expr":"energie_min([8]) == 0"},{"label":"deux bornes","expr":"energie_min([4,9]) == 5"},{"label":"choix de saut","expr":"energie_min([10,30,20,10]) == 20"}],"hints":["dp[i] = coût minimal pour atteindre la borne i.","Pour i >= 2, compare l’arrivée depuis i-1 et depuis i-2."],"solution":"def energie_min(valeurs):\n    if len(valeurs) <= 1:\n        return 0\n    dp = [0, abs(valeurs[1] - valeurs[0])]\n    for i in range(2, len(valeurs)):\n        depuis_1 = dp[i-1] + abs(valeurs[i] - valeurs[i-1])\n        depuis_2 = dp[i-2] + abs(valeurs[i] - valeurs[i-2])\n        dp.append(min(depuis_1, depuis_2))\n    return dp[-1]","tags":["programmation dynamique","robot","coût"]},{"id":"T11-X1","moduleId":"T11","title":"Trouver un pseudo","level":1,"kind":"compléter","prompt":"Complète <code>premiere_position(texte, motif)</code> pour renvoyer la première position du motif, ou -1. N’utilise pas <code>find</code>.","starter":"def premiere_position(texte, motif):\n    for i in range(len(texte) - len(motif) + 1):\n        ok = True\n        for j in range(len(motif)):\n            if __________________:\n                ok = False\n        if ok:\n            return i\n    return -1","tests":[{"label":"début","expr":"premiere_position('pythonforge','python') == 0"},{"label":"milieu","expr":"premiere_position('abcxxabc','xx') == 3"},{"label":"absent","expr":"premiere_position('abc','z') == -1"},{"label":"motif vide","expr":"premiere_position('abc','') == 0"}],"hints":["Compare texte[i+j] avec motif[j].","Dès qu’un caractère diffère, le candidat n’est plus valable."],"solution":"def premiere_position(texte, motif):\n    for i in range(len(texte) - len(motif) + 1):\n        ok = True\n        for j in range(len(motif)):\n            if texte[i+j] != motif[j]:\n                ok = False\n                break\n        if ok:\n            return i\n    return -1","tags":["recherche textuelle","compléter"]},{"id":"T11-X2","moduleId":"T11","title":"Déboguer les occurrences chevauchantes","level":2,"kind":"déboguer","prompt":"La fonction doit compter toutes les occurrences d’un motif, y compris lorsqu’elles se chevauchent. Corrige-la sans utiliser <code>count</code> ni <code>find</code>.","starter":"def nb_occurrences(texte, motif):\n    n = 0\n    i = 0\n    while i <= len(texte) - len(motif):\n        if texte[i:i+len(motif)] == motif:\n            n += 1\n            i += len(motif)\n        else:\n            i += 1\n    return n","tests":[{"label":"chevauchement","expr":"nb_occurrences('aaaa','aa') == 3"},{"label":"classique","expr":"nb_occurrences('banane','an') == 2"},{"label":"absent","expr":"nb_occurrences('abc','z') == 0"}],"hints":["Après une occurrence trouvée, avancer de la longueur du motif fait perdre les chevauchements.","Avance simplement de 1 à chaque tour."],"solution":"def nb_occurrences(texte, motif):\n    if motif == '':\n        return len(texte) + 1\n    n = 0\n    i = 0\n    while i <= len(texte) - len(motif):\n        ok = True\n        for j in range(len(motif)):\n            if texte[i+j] != motif[j]:\n                ok = False\n                break\n        if ok:\n            n += 1\n        i += 1\n    return n","tags":["recherche textuelle","débogage","chevauchement"]},{"id":"T11-X3","moduleId":"T11","title":"Table de saut d’un scanner","level":2,"kind":"écrire","prompt":"Pour un motif non vide de longueur m, construis <code>table_saut(motif)</code> : chaque caractère sauf le dernier est associé à sa distance jusqu’à la fin du motif.","starter":"def table_saut(motif):\n    pass","tests":[{"label":"motif","expr":"table_saut('ABACA') == {'A':2,'B':3,'C':1}"},{"label":"répétition","expr":"table_saut('BANANE') == {'B':5,'A':2,'N':1}"},{"label":"un caractère","expr":"table_saut('X') == {}"}],"hints":["Parcours les indices 0 à m-2.","La valeur est m - 1 - i ; une affectation plus tardive remplace l’ancienne."],"solution":"def table_saut(motif):\n    d = {}\n    m = len(motif)\n    for i in range(m - 1):\n        d[motif[i]] = m - 1 - i\n    return d","tags":["Boyer-Moore","dictionnaire","table de décalage"]},{"id":"T11-X4","moduleId":"T11","title":"Journal de comparaisons","level":2,"kind":"transfert","prompt":"Écris <code>comparaisons_naives(texte, motif)</code> qui renvoie le nombre de comparaisons de caractères effectuées par la recherche naïve jusqu’à la première occurrence, ou jusqu’à la fin si le motif est absent.","starter":"def comparaisons_naives(texte, motif):\n    pass","tests":[{"label":"trouvé immédiatement","expr":"comparaisons_naives('abc','ab') == 2"},{"label":"échecs rapides","expr":"comparaisons_naives('aaaaab','ab') == 10"},{"label":"motif trop long","expr":"comparaisons_naives('ab','abcd') == 0"}],"hints":["Ajoute 1 avant chaque comparaison texte[i+j] / motif[j].","Sur la première différence, sors de la boucle interne."],"solution":"def comparaisons_naives(texte, motif):\n    total = 0\n    for i in range(len(texte) - len(motif) + 1):\n        ok = True\n        for j in range(len(motif)):\n            total += 1\n            if texte[i+j] != motif[j]:\n                ok = False\n                break\n        if ok:\n            return total\n    return total","tags":["recherche textuelle","complexité","instrumentation"]},{"id":"T11-X5","moduleId":"T11","title":"Modération : repérer un mot interdit","level":3,"kind":"écrire","prompt":"Écris <code>contient_motif(texte, motif)</code> qui utilise une stratégie de Horspool simplifiée et renvoie un booléen. N’utilise ni <code>in</code> sur les chaînes, ni <code>find</code>.","starter":"def contient_motif(texte, motif):\n    pass","tests":[{"label":"présent","expr":"contient_motif('salon-nsi-moderation','nsi') is True"},{"label":"absent","expr":"contient_motif('python','java') is False"},{"label":"vide","expr":"contient_motif('abc','') is True"},{"label":"fin","expr":"contient_motif('abcxyz','xyz') is True"}],"hints":["Construis la table avec tous les caractères du motif sauf le dernier.","Compare de droite à gauche puis décale selon le caractère du texte aligné avec la fin."],"solution":"def contient_motif(texte, motif):\n    if motif == '':\n        return True\n    m = len(motif)\n    decalage = {}\n    for i in range(m - 1):\n        decalage[motif[i]] = m - 1 - i\n    pos = 0\n    while pos <= len(texte) - m:\n        j = m - 1\n        while j >= 0 and texte[pos+j] == motif[j]:\n            j -= 1\n        if j < 0:\n            return True\n        pos += decalage.get(texte[pos+m-1], m)\n    return False","tags":["Boyer-Moore-Horspool","modération","transfert"]}];
